package gateway

import (
	"context"
	"fmt"

	"github.com/TrebuchetDynamics/gormes-agent/internal/platform/doctor"
	"github.com/TrebuchetDynamics/gormes-agent/internal/tools"
)

const TermuxLifecycleGuidanceLine = "Termux gateway: foreground/tmux lifecycle; run `gormes gateway` inside tmux; termux-wake-lock and Android battery settings are best-effort only, and Android may still stop background processes."

func TermuxDetected() bool {
	return doctor.IsTermuxEnvironment(nil)
}

func TermuxLifecycleGuidanceError(action string) error {
	return fmt.Errorf("gateway: %s uses the Termux foreground/tmux lifecycle; run `gormes gateway` inside tmux; termux-wake-lock and Android battery settings are best-effort only, and Android may still stop background processes; use `gormes gateway status` and `gormes gateway stop` for runtime control", action)
}

func TermuxNotificationStatusLine() string {
	if !TermuxDetected() {
		return ""
	}
	result := tools.TermuxNotificationSender{}.Status(context.Background())
	switch result.Status {
	case tools.TermuxNotificationStatusAvailable:
		return "Termux notification: available command=termux-notification\n"
	case tools.TermuxNotificationStatusUnavailable:
		return fmt.Sprintf("Termux notification: %s message=%q\n", result.Status, result.Message)
	default:
		return ""
	}
}

package gateway

import (
	"fmt"
	"os"
	"path/filepath"

	"github.com/spf13/cobra"
)

const termuxBootDir = ".termux/boot"
const termuxBootScriptName = "gormes-gateway.sh"

var termuxBootScriptTemplate = `#!/data/data/com.termux/files/usr/bin/sh
# Auto-generated by gormes gateway boot-install
# Starts the Gormes gateway inside tmux on Termux boot.
termux-wake-lock
exec tmux new-session -d -s gormes-gateway "gormes gateway"
`

func NewBootInstallCommand() *cobra.Command {
	return &cobra.Command{
		Use:          "boot-install",
		Short:        "Install Termux:Boot script for gateway auto-start",
		SilenceUsage: true,
		RunE:         runGatewayBootInstall,
	}
}

func NewBootUninstallCommand() *cobra.Command {
	return &cobra.Command{
		Use:          "boot-uninstall",
		Short:        "Remove Termux:Boot script for gateway auto-start",
		SilenceUsage: true,
		RunE:         runGatewayBootUninstall,
	}
}

func runGatewayBootInstall(cmd *cobra.Command, _ []string) error {
	if !TermuxDetected() {
		return fmt.Errorf("gateway boot-install is only available on Termux")
	}
	home := os.Getenv("HOME")
	if home == "" {
		return fmt.Errorf("HOME not set")
	}
	bootDir := filepath.Join(home, termuxBootDir)
	if err := os.MkdirAll(bootDir, 0o755); err != nil {
		return fmt.Errorf("mkdir %s: %w", bootDir, err)
	}
	scriptPath := filepath.Join(bootDir, termuxBootScriptName)
	if err := os.WriteFile(scriptPath, []byte(termuxBootScriptTemplate), 0o755); err != nil {
		return fmt.Errorf("write %s: %w", scriptPath, err)
	}
	fmt.Fprintf(cmd.OutOrStdout(), "gateway boot-install: wrote %s\n", scriptPath)
	fmt.Fprintln(cmd.OutOrStdout(), "gateway boot-install: install the Termux:Boot app and reboot to auto-start")
	return nil
}

func runGatewayBootUninstall(cmd *cobra.Command, _ []string) error {
	if !TermuxDetected() {
		return fmt.Errorf("gateway boot-uninstall is only available on Termux")
	}
	home := os.Getenv("HOME")
	if home == "" {
		return fmt.Errorf("HOME not set")
	}
	scriptPath := filepath.Join(home, termuxBootDir, termuxBootScriptName)
	if err := os.Remove(scriptPath); err != nil {
		if os.IsNotExist(err) {
			fmt.Fprintf(cmd.OutOrStdout(), "gateway boot-uninstall: %s does not exist\n", scriptPath)
			return nil
		}
		return fmt.Errorf("remove %s: %w", scriptPath, err)
	}
	fmt.Fprintf(cmd.OutOrStdout(), "gateway boot-uninstall: removed %s\n", scriptPath)
	return nil
}

package gateway

import (
	"log/slog"
	"os"
	"strings"

	"github.com/TrebuchetDynamics/gormes-agent/internal/config"
	runtimegateway "github.com/TrebuchetDynamics/gormes-agent/internal/gateway"
	"github.com/TrebuchetDynamics/gormes-agent/internal/platform/cli/gormescli/channelruntime"
)

// StartupSecurityReport is the sanitized startup admission result used before
// opening live gateway channels. Config may have weak placeholder credentials
// blanked so the foreground gateway cannot accidentally enable those channels.
type StartupSecurityReport struct {
	Config   config.Config
	Evidence []runtimegateway.AdmissionEvidence
}

// EvaluateStartupSecurity preserves the gateway startup guards for missing
// allowlists and placeholder credentials. It returns a copy of cfg with weak
// credential platforms disabled plus redacted admission evidence for logs.
func EvaluateStartupSecurity(cfg config.Config, lookupEnv func(string) string) StartupSecurityReport {
	if lookupEnv == nil {
		lookupEnv = os.Getenv
	}
	report := StartupSecurityReport{Config: cfg}
	report.Evidence = append(report.Evidence, runtimegateway.CheckStartupAllowlist(runtimegateway.StartupAdmissionInput{
		AllowlistConfigured: StartupAllowlistConfigured(cfg, lookupEnv),
		AllowAll:            StartupAllowAllConfigured(lookupEnv),
	})...)
	credentialReport := runtimegateway.CheckWeakCredentialPlatforms([]runtimegateway.CredentialGuardPlatform{
		{
			Name:    "telegram",
			Enabled: strings.TrimSpace(cfg.Telegram.BotToken) != "",
			Credentials: []runtimegateway.CredentialGuardValue{{
				Field: "bot_token",
				Value: cfg.Telegram.BotToken,
			}},
		},
		{
			Name:    "discord",
			Enabled: cfg.Discord.Enabled(),
			Credentials: []runtimegateway.CredentialGuardValue{{
				Field: "token",
				Value: cfg.Discord.Token,
			}},
		},
		{
			Name:    "slack",
			Enabled: cfg.Slack.Enabled,
			Credentials: []runtimegateway.CredentialGuardValue{
				{Field: "bot_token", Value: cfg.Slack.BotToken},
				{Field: "app_token", Value: cfg.Slack.AppToken},
			},
		},
	})
	report.Evidence = append(report.Evidence, credentialReport.Evidence...)
	for _, platform := range credentialReport.DisabledPlatforms {
		switch platform {
		case "telegram":
			report.Config.Telegram.BotToken = ""
		case "discord":
			report.Config.Discord.Token = ""
		case "slack":
			report.Config.Slack.Enabled = false
			report.Config.Slack.BotToken = ""
			report.Config.Slack.AppToken = ""
		}
	}
	return report
}

// StartupAllowlistConfigured reports whether startup has a scoped gateway
// allowlist configured through config or supported environment variables.
func StartupAllowlistConfigured(cfg config.Config, lookupEnv func(string) string) bool {
	if cfg.Telegram.AllowedChatID != 0 || len(cfg.Telegram.AllowedUserIDs) > 0 {
		return true
	}
	if strings.TrimSpace(cfg.Discord.AllowedChannelID) != "" {
		return true
	}
	if strings.TrimSpace(cfg.Slack.AllowedChannelID) != "" {
		return true
	}
	if len(cfg.Teams.AllowedUserIDs()) > 0 || cfg.Teams.AllowAllUsers {
		return true
	}
	if strings.TrimSpace(cfg.Yuanbao.AllowedConversationID) != "" {
		return true
	}
	if cfg.Navivox.Enabled {
		return true
	}
	if channelruntime.SimpleXStartupAllowlistConfigured(lookupEnv) {
		return true
	}
	for _, key := range []string{
		"SIGNAL_GROUP_ALLOWED_USERS",
		"GORMES_TELEGRAM_ALLOWED_USERS",
		"TELEGRAM_ALLOWED_USERS",
		"GORMES_DISCORD_CHANNEL_ID",
		"GORMES_SLACK_CHANNEL_ID",
		"TEAMS_ALLOWED_USERS",
	} {
		if strings.TrimSpace(lookupEnv(key)) != "" {
			return true
		}
	}
	return false
}

// StartupAllowAllConfigured reports whether startup explicitly opted into
// allowing all gateway users for a supported channel.
func StartupAllowAllConfigured(lookupEnv func(string) string) bool {
	for _, key := range []string{"GATEWAY_ALLOW_ALL_USERS", "TELEGRAM_ALLOW_ALL_USERS", "TEAMS_ALLOW_ALL_USERS", "SIMPLEX_ALLOW_ALL_USERS"} {
		if parseStartupBool(lookupEnv(key)) {
			return true
		}
	}
	return false
}

func parseStartupBool(value string) bool {
	switch strings.ToLower(strings.TrimSpace(value)) {
	case "1", "t", "true", "y", "yes", "on":
		return true
	default:
		return false
	}
}

// LogStartupSecurityEvidence writes redacted startup admission findings to the
// gateway logger while skipping empty evidence entries.
func LogStartupSecurityEvidence(evidence []runtimegateway.AdmissionEvidence, log *slog.Logger) {
	if log == nil {
		log = slog.Default()
	}
	for _, item := range evidence {
		if item.Code == "" {
			continue
		}
		log.Warn("gateway startup admission", "code", item.Code, "platform", item.Platform, "field", item.Field, "message", item.Message)
	}
}

