)

const LifecycleGuidanceLine = "Termux gateway: foreground/tmux lifecycle; run `gormes gateway` inside tmux; termux-wake-lock and Android battery settings are best-effort only, and Android may still stop background processes."

func Detected() bool {
	return doctor.IsTermuxEnvironment(nil)
}

func LifecycleGuidanceError(action string) error {
	return fmt.Errorf("gateway: %s uses the Termux foreground/tmux lifecycle; run `gormes gateway` inside tmux; termux-wake-lock and Android battery settings are best-effort only, and Android may still stop background processes; use `gormes gateway status` and `gormes gateway stop` for runtime control", action)
}

func NotificationStatusLine() string {
	if !Detected() {
		return ""
	}
	result := tools.TermuxNotificationSender{}.Status(context.Background())
	switch result.Status {
	case tools.TermuxNotificationStatusAvailable:
		return "Termux notification: available command=termux-notification\n"
	case tools.TermuxNotificationStatusUnavailable:
		return fmt.Sprintf("Termux notification: %s message=%q\n", result.Status, result.Message)
	default:
		return ""
	}
}

package termuxsupport

import (
	"fmt"
	"os"
	"path/filepath"

	"github.com/spf13/cobra"
)

const bootDir = ".termux/boot"
const bootScriptName = "gormes-gateway.sh"

var bootScriptTemplate = `#!/data/data/com.termux/files/usr/bin/sh
# Auto-generated by gormes gateway boot-install
# Starts the Gormes gateway inside tmux on Termux boot.
termux-wake-lock
exec tmux new-session -d -s gormes-gateway "gormes gateway"
`

func NewBootInstallCommand() *cobra.Command {
	return &cobra.Command{
		Use:          "boot-install",
		Short:        "Install Termux:Boot script for gateway auto-start",
		SilenceUsage: true,
		RunE:         runBootInstall,
	}
}

func NewBootUninstallCommand() *cobra.Command {
	return &cobra.Command{
		Use:          "boot-uninstall",
		Short:        "Remove Termux:Boot script for gateway auto-start",
		SilenceUsage: true,
		RunE:         runBootUninstall,
	}
}

func runBootInstall(cmd *cobra.Command, _ []string) error {
	if !Detected() {
		return fmt.Errorf("gateway boot-install is only available on Termux")
	}
	home := os.Getenv("HOME")
	if home == "" {
		return fmt.Errorf("HOME not set")
	}
	bootDir := filepath.Join(home, bootDir)
	if err := os.MkdirAll(bootDir, 0o755); err != nil {
		return fmt.Errorf("mkdir %s: %w", bootDir, err)
	}
	scriptPath := filepath.Join(bootDir, bootScriptName)
	if err := os.WriteFile(scriptPath, []byte(bootScriptTemplate), 0o755); err != nil {
		return fmt.Errorf("write %s: %w", scriptPath, err)
	}
	fmt.Fprintf(cmd.OutOrStdout(), "gateway boot-install: wrote %s\n", scriptPath)
	fmt.Fprintln(cmd.OutOrStdout(), "gateway boot-install: install the Termux:Boot app and reboot to auto-start")
	return nil
}

func runBootUninstall(cmd *cobra.Command, _ []string) error {
	if !Detected() {
		return fmt.Errorf("gateway boot-uninstall is only available on Termux")
	}
	home := os.Getenv("HOME")
	if home == "" {
		return fmt.Errorf("HOME not set")
	}
	scriptPath := filepath.Join(home, bootDir, bootScriptName)
	if err := os.Remove(scriptPath); err != nil {
		if os.IsNotExist(err) {
			fmt.Fprintf(cmd.OutOrStdout(), "gateway boot-uninstall: %s does not exist\n", scriptPath)
			return nil
		}
		return fmt.Errorf("remove %s: %w", scriptPath, err)
	}
	fmt.Fprintf(cmd.OutOrStdout(), "gateway boot-uninstall: removed %s\n", scriptPath)
	return nil
}

